const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
(async()=>{for(const file of ['index.html','flutter_bootstrap.js','main.dart.js']){const res=await fetch('https://bepxinh-b0be7.web.app/'+file+'?verify=recipe-reports');assert.equal(res.status,200);assert.equal(sha(Buffer.from(await res.arrayBuffer())),sha(fs.readFileSync('build/web/'+file)),file);}console.log('PASS: live app HTML/bootstrap/main.dart.js match production build');})().catch(e=>{console.error(e.message);process.exitCode=1});
